package com.example.tgserver

import android.content.Context
import android.os.Build
import kotlinx.coroutines.flow.MutableStateFlow
import org.drinkless.td.libcore.telegram.Client
import org.drinkless.td.libcore.telegram.TdApi
import java.io.File

sealed class AuthState {
    object Idle : AuthState()
        object WaitPhone : AuthState()
            object WaitCode : AuthState()
                object WaitPassword : AuthState()
                    object Ready : AuthState()
                        data class Error(val message: String) : AuthState()
                        }

                        /**
                         * Singleton TDLib wrapper. Lives for the app process's lifetime.
                          * Login happens once in MainActivity; StreamService (same process)
                           * reuses this same object with no extra wiring needed.
                            *
                             * IMPORTANT: TDLib's ExceptionHandler docs say "If it is null, exceptions
                              * will be ignored" - meaning any crash in our update-handling code was
                               * previously being silently swallowed, which is why the login screen
                                * could hang forever with zero feedback. Both exception handlers are now
                                 * wired to Log.e AND to authState, so failures are visible instead of
                                  * silent - check Logcat with tag "TGServer" if the on-screen message
                                   * isn't enough detail.
                                    */
                                    object TelegramClient {

                                        val authState = MutableStateFlow<AuthState>(AuthState.Idle)

                                            private var client: Client? = null

                                                private val fileListeners = HashMap<Int, MutableList<(TdApi.File) -> Unit>>()
                                                    private val fileListenersLock = Any()

                                                        fun init(context: Context, apiId: Int, apiHash: String) {
                                                                if (client != null) {
                                                                            FileLogger.log("init() called again, client already exists - ignoring")
                                                                                        return
                                                                                                }

                                                                                                        try {
                                                                                                                    // Catches uncaught exceptions on ANY thread, including TDLib's own
                                                                                                                                // background "TDLib thread". If the app hangs with no crash and no
                                                                                                                                            // logged exception, the real error is very likely being swallowed
                                                                                                                                                        // inside TDLib's own internal loop before it ever reaches our
                                                                                                                                                                    // handlers below - this is the last line of defense to catch that.
                                                                                                                                                                                val previousHandler = Thread.getDefaultUncaughtExceptionHandler()
                                                                                                                                                                                            Thread.setDefaultUncaughtExceptionHandler { thread, throwable ->
                                                                                                                                                                                                            FileLogger.error("UNCAUGHT exception on thread '${thread.name}'", throwable)
                                                                                                                                                                                                                            authState.value = AuthState.Error("Crash on thread '${thread.name}': ${throwable.message}")
                                                                                                                                                                                                                                            previousHandler?.uncaughtException(thread, throwable)
                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                    val dbDir = File(context.filesDir, "tdlib").absolutePath
                                                                                                                                                                                                                                                                                FileLogger.log("Creating TDLib client, dbDir=$dbDir apiId=$apiId")

                                                                                                                                                                                                                                                                                            client = Client.create(
                                                                                                                                                                                                                                                                                                            { update ->
                                                                                                                                                                                                                                                                                                                                try {
                                                                                                                                                                                                                                                                                                                                                        FileLogger.log("Update received: ${update.javaClass.simpleName}")
                                                                                                                                                                                                                                                                                                                                                                                handleUpdate(update)
                                                                                                                                                                                                                                                                                                                                                                                                    } catch (e: Throwable) {
                                                                                                                                                                                                                                                                                                                                                                                                                            FileLogger.error("Exception while handling update ${update.javaClass.simpleName}", e)
                                                                                                                                                                                                                                                                                                                                                                                                                                                    authState.value = AuthState.Error("Update handler crashed: ${e.message}")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        { e ->
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            FileLogger.error("TDLib updatesExceptionHandler fired", e)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                authState.value = AuthState.Error("TDLib update exception: ${e.message}")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                { e ->
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    FileLogger.error("TDLib defaultExceptionHandler fired", e)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        authState.value = AuthState.Error("TDLib exception: ${e.message}")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                FileLogger.log("Client.create() returned, client=$client")

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            val parameters = TdApi.TdlibParameters().apply {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            databaseDirectory = dbDir
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            useFileDatabase = true
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            useChatInfoDatabase = true
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            useMessageDatabase = true
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            useSecretChats = false
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            this.apiId = apiId
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            this.apiHash = apiHash
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            systemLanguageCode = "en"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            deviceModel = "Android"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            systemVersion = Build.VERSION.RELEASE ?: "Unknown"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            applicationVersion = "0.1"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            enableStorageOptimizer = true
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    FileLogger.log("Sending SetTdlibParameters...")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                client?.send(TdApi.SetTdlibParameters(parameters)) { result ->
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                FileLogger.log("SetTdlibParameters result: $result")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (result is TdApi.Error) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    authState.value = AuthState.Error("SetTdlibParameters failed: ${result.message}")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } catch (e: Throwable) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    FileLogger.error("init() threw an exception", e)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                authState.value = AuthState.Error("Failed to start TDLib: ${e.message}")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                fun submitPhone(phone: String) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        FileLogger.log("submitPhone called")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                client?.send(TdApi.SetAuthenticationPhoneNumber(phone, null)) { result ->
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            FileLogger.log("SetAuthenticationPhoneNumber result: $result")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (result is TdApi.Error) authState.value = AuthState.Error("Phone rejected: ${result.message}")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        fun submitCode(code: String) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                FileLogger.log("submitCode called")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        client?.send(TdApi.CheckAuthenticationCode(code)) { result ->
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    FileLogger.log("CheckAuthenticationCode result: $result")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (result is TdApi.Error) authState.value = AuthState.Error("Code rejected: ${result.message}")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                fun submitPassword(password: String) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        FileLogger.log("submitPassword called")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                client?.send(TdApi.CheckAuthenticationPassword(password)) { result ->
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            FileLogger.log("CheckAuthenticationPassword result: $result")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (result is TdApi.Error) authState.value = AuthState.Error("Password rejected: ${result.message}")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        fun isReady(): Boolean = authState.value is AuthState.Ready

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            fun rawClient(): Client = client ?: error("TelegramClient.init() not called yet")

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                fun addFileListener(fileId: Int, listener: (TdApi.File) -> Unit) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        synchronized(fileListenersLock) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    fileListeners.getOrPut(fileId) { mutableListOf() }.add(listener)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    fun removeFileListener(fileId: Int, listener: (TdApi.File) -> Unit) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            synchronized(fileListenersLock) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        fileListeners[fileId]?.remove(listener)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        private fun handleUpdate(update: TdApi.Object) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                when (update) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            is TdApi.UpdateAuthorizationState -> handleAuthState(update.authorizationState)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        is TdApi.UpdateFile -> dispatchFileUpdate(update.file)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    else -> { /* ignore everything else */ }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    private fun handleAuthState(state: TdApi.AuthorizationState) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            FileLogger.log("Auth state changed: ${state.javaClass.simpleName}")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    when (state) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                is TdApi.AuthorizationStateWaitEncryptionKey -> {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                client?.send(TdApi.CheckDatabaseEncryptionKey()) { result ->
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    FileLogger.log("CheckDatabaseEncryptionKey result: $result")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            is TdApi.AuthorizationStateWaitPhoneNumber -> authState.value = AuthState.WaitPhone
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        is TdApi.AuthorizationStateWaitCode -> authState.value = AuthState.WaitCode
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    is TdApi.AuthorizationStateWaitPassword -> authState.value = AuthState.WaitPassword
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                is TdApi.AuthorizationStateReady -> authState.value = AuthState.Ready
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            is TdApi.AuthorizationStateClosed -> authState.value = AuthState.Error("Session closed")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        else -> { /* e.g. WaitTdlibParameters, LoggingOut, Closing - just logged above */ }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        private fun dispatchFileUpdate(file: TdApi.File) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                val listeners = synchronized(fileListenersLock) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            fileListeners[file.id]?.toList() ?: emptyList()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            listeners.forEach { it(file) }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                